import boto3
for r in ['{{REGION_A}}','{{REGION_B}}','{{REGION_C}}']:
    c=boto3.client('ec2',region_name=r)
    for p in c.get_paginator('describe_instances').paginate(Filters=[{'Name':'instance-state-name','Values':['running']}]):
        for res in p['Reservations']:
            for i in res['Instances']:
                n=[t['Value'] for t in i.get('Tags',[]) if t['Key']=='Name']
                print(r,i['InstanceId'],n[:1],i.get('PrivateIpAddress'))

import boto3
for p in boto3.client('lambda').get_paginator('list_functions').paginate():
    for f in p['Functions']:
        print(f['FunctionName'],f.get('Runtime'))

import boto3
for p in boto3.client('cloudwatch').get_paginator('describe_alarms').paginate(StateValue='ALARM'):
    for a in p['MetricAlarms']+p['CompositeAlarms']:
        print(a['AlarmName'],a['StateReason'])

import boto3,datetime as d
t=d.date.today()
r=boto3.client('ce').get_cost_and_usage(TimePeriod={'Start':str(t-d.timedelta(30)),'End':str(t)},Granularity='MONTHLY',Metrics=['UnblendedCost'],GroupBy=[{'Type':'DIMENSION','Key':'SERVICE'}])
for x in r['ResultsByTime']:
    for g in x['Groups']:
        print(g['Keys'][0],g['Metrics']['UnblendedCost']['Amount'])

import boto3
c=boto3.client('ec2')
for p in c.get_paginator('describe_security_groups').paginate(Filters=[{'Name':'ip-permission.cidr','Values':['0.0.0.0/0']},{'Name':'ip-permission.from-port','Values':['22']}]):
    for g in p['SecurityGroups']:
        print(g['GroupId'],g['GroupName'],g['VpcId'])
